/*
 * Meridian design system — registry entry stylesheet.
 *
 * Generated by `pnpm --filter @designharness/registry build` (packages/registry/scripts/build.mjs).
 * Do not edit: it is rebuilt from @designharness/tokens’ compiled artifact and the authored
 * component CSS in @designharness/ui, in the cascade order @designharness/ui/styles.css declares.
 *
 * Import this file once from the application entry point, after Tailwind, and every
 * `var(--…)` in the sheets below resolves against the token artifact.
 */

@import './tokens.css';
@import './tailwind-theme.css';
@import './base.css';
@import './button.css';
@import './input.css';
@import './combobox.css';
@import './dialog.css';
@import './data-table.css';
@import './motion.css';
